import {FEEDS, NETWORKS, addressMatches, fetchNewPools, fetchPublicSource, mergeArticles} from './public-radar.mjs';

const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>v===null||v===undefined?'—':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',notation:'compact',maximumFractionDigits:1}).format(v);
const num=v=>v===null||v===undefined?'—':Number(v).toLocaleString('en-US');
const age=time=>{const minutes=Math.max(0,Math.round((Date.now()-time)/60000));return minutes<60?`${minutes}m old`:minutes<1440?`${Math.floor(minutes/60)}h old`:`${Math.floor(minutes/1440)}d old`};
const state={hours:36,query:''};
const data={articles:[],coins:[]};
let loading=false;

function qualified(c){return Number.isFinite(c.poolCreated)&&c.liquidity>=3000&&((c.buys??0)+(c.sells??0)>=5);}
function score(c){const ageHours=Math.max(0,(Date.now()-c.poolCreated)/3600000);const freshness=Math.max(0,1-ageHours/36)*45;const liquidity=Math.min(20,Math.log10(Math.max(1,c.liquidity))*4);const activity=Math.min(25,Math.log10(Math.max(1,(c.volume??0)+(c.buyers??0)*100))*5);const buys=Math.min(10,Math.log10(Math.max(1,c.buyers??0))*4);return freshness+liquidity+activity+buys;}
function candidates(){const query=state.query.trim().toLowerCase(),cutoff=Date.now()-state.hours*3600000;return data.coins.filter(c=>qualified(c)&&c.poolCreated>=cutoff&&(!query||`${c.name} ${c.symbol} ${c.contract_address}`.toLowerCase().includes(query))).sort((a,b)=>score(b)-score(a));}
function evidence(c){return data.articles.filter(a=>addressMatches({posts:[a]},[c]).length);}
function card(c,posts,index,kind){const explanation=posts.length?`<div class="story-answer"><span>What it is</span><p>Public coverage contains this exact contract. Open the evidence to review the context before treating it as a narrative match.</p></div><div class="evidence-links">${posts.slice(0,2).map(p=>`<a href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">${esc(p.publisher)} · ${esc(p.title)} ↗</a>`).join('')}</div>`:`<div class="story-answer pending"><span>What it is</span><p>Context pending. The new-pool feed identifies this contract, but the connected sources do not yet explain the name, meme, person, or event behind it.</p></div>`;return `<article class="new-coin-card"><div class="coin-head"><span class="rank">${String(index+1).padStart(2,'0')}</span><div><h3>$${esc(c.symbol)}</h3><small>${esc(c.name)} · ${esc(c.chain)} · ${esc(age(c.poolCreated))}</small></div><span class="context-state ${kind}">${posts.length?'Evidence found':'Context pending'}</span></div>${explanation}<dl class="new-metrics"><div><dt>Liquidity</dt><dd>${money(c.liquidity)}</dd></div><div><dt>24H volume</dt><dd>${money(c.volume)}</dd></div><div><dt>Pool buyers</dt><dd>${num(c.buyers)}</dd></div></dl><div class="coin-footer"><code title="${esc(c.contract_address)}">${esc(c.contract_address)}</code><a class="text-button" href="./?query=${encodeURIComponent(c.contract_address)}">Research ↗</a></div></article>`;}
function render(){const rows=candidates(),explained=rows.filter(c=>evidence(c).length),pending=rows.filter(c=>!evidence(c).length);$('#explained-count').textContent=explained.length;$('#pending-count').textContent=pending.length;$('#explained').innerHTML=explained.length?explained.map((c,i)=>card(c,evidence(c),i,'found')).join(''):'<div class="new-empty"><strong>No supported story matches yet.</strong>Exact contract evidence will appear here when the connected sources mention a candidate.</div>';$('#pending').innerHTML=pending.length?pending.slice(0,30).map((c,i)=>card(c,[],i,'pending')).join(''):'<div class="new-empty"><strong>No qualified new pools in this window.</strong>Try 36H or refresh the discovery feeds.</div>';$('#status').textContent=loading?'Refreshing public discovery feeds…':`${rows.length} qualified new-pool candidates · ${state.hours}H window · Solana + Base · story evidence requires an exact contract match`;}
async function refresh(){if(loading)return;loading=true;render();const results=await Promise.allSettled([...NETWORKS.map(network=>fetchNewPools(network)),...FEEDS.map(feed=>fetchPublicSource(feed))]);data.coins=[];data.articles=[];results.slice(0,NETWORKS.length).forEach(result=>{if(result.status==='fulfilled')data.coins.push(...result.value)});results.slice(NETWORKS.length).forEach(result=>{if(result.status==='fulfilled')data.articles=mergeArticles(data.articles,result.value)});loading=false;render();}
document.addEventListener('click',event=>{const button=event.target.closest('[data-hours]');if(!button)return;state.hours=Number(button.dataset.hours);document.querySelectorAll('[data-hours]').forEach(x=>x.setAttribute('aria-pressed',String(x===button)));render();});
$('#query').addEventListener('input',event=>{state.query=event.target.value;render();});
$('#refresh').addEventListener('click',refresh);
render();refresh();
